gotchas.cssFix:
/* knowledge:options-collapse-clips-design-trigger — size Options host; hide only SDK ••• glyph */
.vc-options { width: 16px !important; height: 16px !important; overflow: visible !important; }
.vc-options svg.comment-dialog-options-dropdown-trigger { width: 0 !important; height: 0 !important; opacity: 0 !important; pointer-events: none !important; }
.vc-options .options-trigger-container,
.vc-options .mat-mdc-menu-trigger,
.vc-options .v-dropdown-menu-trigger { width: 16px !important; height: 16px !important; overflow: visible !important; opacity: 1 !important; pointer-events: auto !important; }

/* knowledge:sidebar-flex-scrollport */
velt-comments-sidebar { height: 100% !important; max-height: 100% !important; min-height: 0 !important; overflow: hidden !important; }
.vc-panel, app-comment-sidebar-panel.vc-panel { flex: 1 1 0 !important; min-height: 0 !important; overflow: hidden !important; height: 100% !important; }
.vc-list, app-comment-sidebar-list.vc-list { flex: 1 1 0 !important; min-height: 0 !important; overflow: auto !important; }
.velt-sidebar-content { flex: 0 0 auto !important; height: auto !important; overflow: visible !important; }
